// sglang's EAGLE draft token at topk 1 (eagle_worker_v2_draft_top1@1.0): each row's highest float32
// logit's index, as torch.argmax (NaN highest, the first of equal values), and p = 1. Block (b, row)
// folds the float4s b * THREADS + t, + BLOCKS * THREADS, .. into one 64-bit key, the logit's order
// over the index's complement, and the row's slot keeps the highest key (atomic max); the row's last
// block to count itself done writes the outputs and clears the slot and the count for the next call.
// The order is Infera-Flash's lm_head_argmax's (csrc/glm5/lm_head.hip).
// Each block's count is a release at agent scope, and with more rows they add up: from 5 rows
// top1_wide_kernel counts half the blocks a row, each twice as wide, each row's slot on cache lines
// of its own, and only a row's last block acquires. Both leave the state zero, so any rows follow.
#include <ATen/ATen.h>
#include <ATen/hip/HIPContext.h>
#include <ATen/hip/impl/HIPGuardImplMasqueradingAsCUDA.h>
#include <c10/hip/HIPException.h>
#include <torch/library.h>

namespace {

constexpr int     WAVE     = 64;
constexpr int     THREADS  = 256;
constexpr int     BLOCKS   = 32; // per row
constexpr int64_t MAX_ROWS = 4096;

struct RowSlot {
    unsigned long long key;
    unsigned int       done;
    unsigned int       unused;
};
// zeroed once and kept: each call's last block clears what it used
constexpr int64_t STATE_BYTES = MAX_ROWS * sizeof(RowSlot);

// top1_kernel up to NARROW_ROWS rows, top1_wide_kernel above while its slots fit in the state
constexpr int64_t NARROW_ROWS     = 4;
constexpr int     WIDE_THREADS    = 512;
constexpr int     WIDE_BLOCKS     = 16; // per row
constexpr int64_t WIDE_SLOT_BYTES = 256;

// a logit as torch.argmax orders it, as an integer above 0: NaN highest, -0 as +0
__device__ __forceinline__ unsigned int order_of(float v) {
    const unsigned int bits = __float_as_uint(v) == 0x80000000u ? 0u : __float_as_uint(v);
    if ((bits & 0x7fffffffu) > 0x7f800000u) {
        return 0xffffffffu;
    }
    return bits & 0x80000000u ? ~bits : bits | 0x80000000u;
}

// higher logits first, then lower indices
__device__ __forceinline__ unsigned long long key_of(float v, unsigned int index) {
    return static_cast<unsigned long long>(order_of(v)) << 32 | ~index;
}

__device__ __forceinline__ unsigned long long higher(unsigned long long a, unsigned long long b) {
    return a > b ? a : b;
}

__global__ __launch_bounds__(THREADS) void top1_kernel(const float *logits, int vocab, float *topk_p,
                                                       int64_t *topk_index, RowSlot *slots) {
    const int     row  = blockIdx.y;
    const float4 *x    = reinterpret_cast<const float4 *>(logits + static_cast<size_t>(row) * vocab);
    unsigned long long best = 0;
    for (int i = blockIdx.x * THREADS + threadIdx.x; i < vocab / 4; i += BLOCKS * THREADS) {
        const float4 v = x[i];
        best           = higher(best, higher(higher(key_of(v.x, 4 * i), key_of(v.y, 4 * i + 1)),
                                             higher(key_of(v.z, 4 * i + 2), key_of(v.w, 4 * i + 3))));
    }
    for (int width = WAVE / 2; width >= 1; width /= 2) {
        best = higher(best, __shfl_xor(best, width));
    }
    __shared__ unsigned long long waves[THREADS / WAVE];
    if (threadIdx.x % WAVE == 0) {
        waves[threadIdx.x / WAVE] = best;
    }
    __syncthreads();
    if (threadIdx.x != 0) {
        return;
    }
    for (int w = 1; w < THREADS / WAVE; ++w) {
        best = higher(best, waves[w]);
    }
    RowSlot &slot = slots[row];
    __hip_atomic_fetch_max(&slot.key, best, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
    if (__hip_atomic_fetch_add(&slot.done, 1u, __ATOMIC_ACQ_REL, __HIP_MEMORY_SCOPE_AGENT) !=
        BLOCKS - 1) {
        return;
    }
    const unsigned long long key =
        __hip_atomic_load(&slot.key, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
    topk_index[row] = ~static_cast<unsigned int>(key);
    topk_p[row]     = 1.0f;
    __hip_atomic_store(&slot.key, 0ull, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
    __hip_atomic_store(&slot.done, 0u, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
}

// top1_kernel's fold at WIDE_BLOCKS blocks of WIDE_THREADS a row; row r's slot at byte
// r * WIDE_SLOT_BYTES of the state
__global__ __launch_bounds__(WIDE_THREADS) void top1_wide_kernel(const float *logits, int vocab,
                                                                 float *topk_p, int64_t *topk_index,
                                                                 unsigned char *state) {
    const int     row  = blockIdx.y;
    const float4 *x    = reinterpret_cast<const float4 *>(logits + static_cast<size_t>(row) * vocab);
    unsigned long long best = 0;
    for (int i = blockIdx.x * WIDE_THREADS + threadIdx.x; i < vocab / 4;
         i += WIDE_BLOCKS * WIDE_THREADS) {
        const float4 v = x[i];
        best           = higher(best, higher(higher(key_of(v.x, 4 * i), key_of(v.y, 4 * i + 1)),
                                             higher(key_of(v.z, 4 * i + 2), key_of(v.w, 4 * i + 3))));
    }
    for (int width = WAVE / 2; width >= 1; width /= 2) {
        best = higher(best, __shfl_xor(best, width));
    }
    __shared__ unsigned long long waves[WIDE_THREADS / WAVE];
    if (threadIdx.x % WAVE == 0) {
        waves[threadIdx.x / WAVE] = best;
    }
    __syncthreads();
    if (threadIdx.x != 0) {
        return;
    }
    for (int w = 1; w < WIDE_THREADS / WAVE; ++w) {
        best = higher(best, waves[w]);
    }
    RowSlot &slot = *reinterpret_cast<RowSlot *>(state + row * WIDE_SLOT_BYTES);
    __hip_atomic_fetch_max(&slot.key, best, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
    // the max before the count, as top1_kernel's acq_rel count orders it
    __builtin_amdgcn_fence(__ATOMIC_RELEASE, "agent");
    if (__hip_atomic_fetch_add(&slot.done, 1u, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT) !=
        WIDE_BLOCKS - 1) {
        return;
    }
    __builtin_amdgcn_fence(__ATOMIC_ACQUIRE, "agent");
    const unsigned long long key =
        __hip_atomic_load(&slot.key, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
    topk_index[row] = ~static_cast<unsigned int>(key);
    topk_p[row]     = 1.0f;
    __hip_atomic_store(&slot.key, 0ull, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
    __hip_atomic_store(&slot.done, 0u, __ATOMIC_RELAXED, __HIP_MEMORY_SCOPE_AGENT);
}

void run(const at::Tensor &logits, at::Tensor &topk_p, at::Tensor &topk_index, at::Tensor &state) {
    const int64_t rows = logits.size(0), vocab = logits.size(1);
    TORCH_CHECK(rows >= 1 && rows <= MAX_ROWS, "1 to ", MAX_ROWS, " rows");
    TORCH_CHECK(vocab % 4 == 0 && reinterpret_cast<uintptr_t>(logits.data_ptr()) % 16 == 0,
                "16-byte aligned rows");
    TORCH_CHECK(state.nbytes() >= STATE_BYTES, "state: ", STATE_BYTES, " bytes");
    const at::hip::OptionalHIPGuardMasqueradingAsCUDA guard(logits.device());
    if (rows > NARROW_ROWS && rows * WIDE_SLOT_BYTES <= STATE_BYTES) {
        top1_wide_kernel<<<dim3(WIDE_BLOCKS, rows), WIDE_THREADS, 0,
                           at::hip::getCurrentHIPStream()>>>(
            logits.data_ptr<float>(), static_cast<int>(vocab), topk_p.data_ptr<float>(),
            topk_index.data_ptr<int64_t>(), static_cast<unsigned char *>(state.data_ptr()));
    } else {
        top1_kernel<<<dim3(BLOCKS, rows), THREADS, 0, at::hip::getCurrentHIPStream()>>>(
            logits.data_ptr<float>(), static_cast<int>(vocab), topk_p.data_ptr<float>(),
            topk_index.data_ptr<int64_t>(), static_cast<RowSlot *>(state.data_ptr()));
    }
    C10_HIP_CHECK(hipGetLastError());
}

} // namespace

#define TORCH_LIBRARY_EXPAND(ns, m) TORCH_LIBRARY(ns, m)
TORCH_LIBRARY_EXPAND(TORCH_EXTENSION_NAME, m) {
    m.def("run(Tensor logits, Tensor(a!) topk_p, Tensor(b!) topk_index, Tensor(c!) state) -> ()",
          &run);
}
